int strlen(char *string) {
    int length = 0;
    while (string[length] != '\0') {
        ++length;
    }
    return length;
}

int text_length(const char *s) {
    int n = 0;
    while (s[n] != '\0') ++n;
    return n;
}

size_t pointer_length(const char *s) {
    const char *p = s;
    while (*p != '\0') ++p;
    return (size_t)(p - s);
}

int suffix_length(const char *s, int start) {
    int n = 0;
    while (s[start + n] != '\0') ++n;
    return n;
}

size_t bounded_length(const char *s, size_t limit) {
    size_t n = 0;
    while (n < limit && s[n] != '\0') ++n;
    return n;
}

int count_char(const char *s, char target) {
    int count = 0;
    for (int i = 0; s[i] != '\0'; ++i) {
        if (s[i] == target) ++count;
    }
    return count;
}

int prefix_length(const char *s, char stop) {
    int n = 0;
    while (s[n] != '\0' && s[n] != stop) ++n;
    return n;
}

int last_char_index(const char *s) {
    int n = 0;
    while (s[n] != '\0') ++n;
    return n - 1;
}

int has_at_least(const char *s, int n) {
    int i = 0;
    while (i < n) {
        if (s[i] == '\0') return 0;
        ++i;
    }
    return 1;
}

int checked_length(const char *s) {
    if (s == NULL) return -1;
    int n = 0;
    while (s[n] != '\0') ++n;
    return n;
}

void string_lengths(const char *const strings[], int count, int out[]) {
    for (int i = 0; i < count; ++i) {
        int n = 0;
        while (strings[i][n] != '\0') ++n;
        out[i] = n;
    }
}

void *memset(void *ptr, char byte, int size) {
    unsigned char *p = ptr;
    for (int i = 0; i < size; ++i) {
        p[i] = (unsigned char)byte;
    }
    return ptr;
}

void *fill_bytes(void *ptr, unsigned char byte, size_t n) {
    unsigned char *p = ptr;
    for (size_t i = 0; i < n; ++i) p[i] = byte;
    return ptr;
}

void zero_bytes(void *ptr, size_t n) {
    unsigned char *p = ptr;
    for (size_t i = 0; i < n; ++i) p[i] = 0;
}

unsigned char *fill_range(unsigned char *buffer, size_t start, size_t count, unsigned char byte) {
    for (size_t i = 0; i < count; ++i) buffer[start + i] = byte;
    return buffer;
}

void *fill_reverse(void *ptr, unsigned char byte, size_t n) {
    unsigned char *p = ptr;
    while (n > 0) {
        --n;
        p[n] = byte;
    }
    return ptr;
}

void *fill_alternating(void *ptr, unsigned char first, unsigned char second, size_t n) {
    unsigned char *p = ptr;
    for (size_t i = 0; i < n; ++i) {
        p[i] = i % 2 == 0 ? first : second;
    }
    return ptr;
}

void *fill_after(void *ptr, size_t offset, unsigned char byte, size_t n) {
    unsigned char *p = ptr;
    for (size_t i = 0; i < n; ++i) p[offset + i] = byte;
    return ptr;
}

void *fill_checked(void *ptr, unsigned char byte, int count) {
    unsigned char *p = ptr;
    for (int i = 0; i < count; ++i) p[i] = byte;
    return ptr;
}

void *fill_value(void *ptr, int value, size_t n) {
    unsigned char *p = ptr;
    unsigned char byte = (unsigned char)value;
    for (size_t i = 0; i < n; ++i) p[i] = byte;
    return ptr;
}

size_t fill_zeros(void *ptr, unsigned char byte, size_t n) {
    unsigned char *p = ptr;
    size_t count = 0;
    for (size_t i = 0; i < n; ++i) {
        if (p[i] == 0) { p[i] = byte; ++count; }
    }
    return count;
}

unsigned char *fill_end(void *ptr, unsigned char byte, size_t n) {
    unsigned char *p = ptr;
    for (size_t i = 0; i < n; ++i) *p++ = byte;
    return p;
}
